          code: "# 按定义式实现 DFT，检查谱峰位置、幅度与频率分辨率\nimport math\n\nN = 32\nfs = 32.0          # 采样率 Hz\nf0 = 4.0           # 信号频率 Hz\ndf = fs / N        # 频率分辨率 Hz\n\ndef dft(x):\n    n = len(x)\n    out = []\n    for k in range(n):\n        re = 0.0\n        im = 0.0\n        for j in range(n):\n            ang = -2.0 * math.pi * k * j / n\n            re += x[j] * math.cos(ang)\n            im += x[j] * math.sin(ang)\n        out.append((re, im))\n    return out\n\nsig = [math.cos(2.0 * math.pi * f0 * i / fs) for i in range(N)]\nspec = dft(sig)\nmag = [2.0 * math.hypot(re, im) / N for re, im in spec]   # 单边幅度谱\nkmax = max(range(N // 2 + 1), key=lambda k: mag[k])\nprint('频率分辨率 df =', df, 'Hz    记录时长 T =', N / fs, 's')\nprint('奈奎斯特频率 =', fs / 2, 'Hz')\nprint('谱峰落在 k =', kmax, '对应频率', kmax * df, 'Hz')\nprint('峰值幅度 =', round(mag[kmax], 6), '（原信号幅度为 1）')\nprint('直流分量幅度 =', round(mag[0], 9))\n"
