          code: "# Metropolis 抽样：一维伊辛链，与解析值 -J*tanh(J/kT) 对照\nimport math\nimport random\n\nrandom.seed(3)\nN = 64\nJ = 1.0\nkT = 2.0\nbeta = 1.0 / kT\nsweeps = 2000\n\ns = [1] * N          # 初态：所有自旋朝上\n\ndef energy(s):\n    e = 0.0\n    for i in range(N):\n        e -= J * s[i] * s[(i + 1) % N]      # 周期性边界\n    return e\n\naccepted = 0\ne_sum = 0.0\nfor step in range(sweeps):\n    for i in range(N):\n        dE = 2.0 * J * s[i] * (s[(i - 1) % N] + s[(i + 1) % N])\n        if dE <= 0.0 or random.random() < math.exp(-beta * dE):\n            s[i] = -s[i]\n            accepted += 1\n    e_sum += energy(s)          # 每个 sweep 记录一次能量\nprint('模拟 <E>/N =', round(e_sum / sweeps / N, 6))\nprint('解析 -tanh(J/kT) =', round(-math.tanh(beta * J), 6))\nprint('接受率 =', round(accepted / (sweeps * N), 4))\nprint('末态 |M|/N =', round(abs(sum(s)) / N, 4))\n"
