          code: "# 幂法求主本征值：一维链的格点矩阵 A = 三对角(-1, 2, -1)\n# 它同时是「N 个弹簧串成的珠链（两端固定）」的刚度矩阵\nimport math\n\nN = 10\nA = [[0.0] * N for _ in range(N)]\nfor i in range(N):\n    A[i][i] = 2.0\n    if i + 1 < N:\n        A[i][i + 1] = -1.0\n        A[i + 1][i] = -1.0\n\ndef matvec(M, v):\n    return [sum(M[i][j] * v[j] for j in range(len(v))) for i in range(len(v))]\n\nv = [float(i + 1) for i in range(N)]        # 斜线初值：与主本征向量有非零重叠\nlam = 0.0\nprint('迭代次数   主本征值估计      与解析值之差')\nfor k in range(1, 401):\n    w = matvec(A, v)\n    norm = math.sqrt(sum(x * x for x in w))\n    v = [x / norm for x in w]                       # 归一化，防止数值溢出\n    new = sum(v[i] * matvec(A, v)[i] for i in range(N))   # 瑞利商\n    if k == 1 or k % 100 == 0:\n        print(f'{k:6d}   {new:.10f}   {abs(new - lam):.3e}')\n    lam = new\nexact = 4.0 * math.cos(math.pi / (2 * (N + 1))) ** 2\nprint('解析值 4cos^2(pi/(2(N+1))) =', round(exact, 10))\nprint('相对误差 =', f'{abs(lam - exact) / exact:.3e}')"
